import{_ as r,o as n,c as e,a6 as o}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"渲染光谱 · CSR / SSR / SSG / ISR 一图看清","description":"CSR、SSR、SSG、ISR 四个词，本质是同一个问题的不同答案——「什么时候、在哪里，把页面渲染出来」。这一章把它们摆进一张全景图，讲清各自的新鲜度、TTFB、扛量与场景，也为后面的缓存讨论立好坐标系。","frontmatter":{"title":"渲染光谱 · CSR / SSR / SSG / ISR 一图看清","description":"CSR、SSR、SSG、ISR 四个词，本质是同一个问题的不同答案——「什么时候、在哪里，把页面渲染出来」。这一章把它们摆进一张全景图，讲清各自的新鲜度、TTFB、扛量与场景，也为后面的缓存讨论立好坐标系。","source":"https://daiw.org/manual/ssr/rendering-spectrum"},"headers":[],"relativePath":"manual/computer-programming/ssr/rendering-spectrum.md","filePath":"manual/computer-programming/ssr/rendering-spectrum.md"}'),s={name:"manual/computer-programming/ssr/rendering-spectrum.md"};function a(g,t,S,d,i,l){return n(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="渲染光谱-·-csr-ssr-ssg-isr-一图看清" tabindex="-1">渲染光谱 · CSR / SSR / SSG / ISR 一图看清 <a class="header-anchor" href="#渲染光谱-·-csr-ssr-ssg-isr-一图看清" aria-label="Permalink to &quot;渲染光谱 · CSR / SSR / SSG / ISR 一图看清&quot;">​</a></h1><p>CSR、SSR、SSG、ISR 四个词，本质是同一个问题的不同答案——「什么时候、在哪里，把页面渲染出来」。这一章把它们摆进一张全景图，讲清各自的新鲜度、TTFB、扛量与场景，也为后面的缓存讨论立好坐标系。</p><p>CSR、SSR、SSG、ISR——这四个缩写是 SSR 世界里最容易让人晕的地方。但只要抓住一个核心问题，它们立刻就理顺了：</p><blockquote><p><strong>页面到底是「什么时候」、在「哪里」被渲染出来的？</strong></p></blockquote><p>「什么时候」有三个答案：<strong>构建时</strong>、<strong>请求时</strong>、<strong>运行时（在客户端）</strong>。四种策略，就是这几个答案的不同组合。</p><h2 id="四种策略-各在光谱的一端" tabindex="-1">四种策略，各在光谱的一端 <a class="header-anchor" href="#四种策略-各在光谱的一端" aria-label="Permalink to &quot;四种策略，各在光谱的一端&quot;">​</a></h2><p><strong>CSR（客户端渲染）</strong> —— <strong>运行时，在用户的浏览器里</strong>渲染。服务器只发空壳。→ 上一站讲过的<a href="/Front2Full/manual/computer-programming/ssr/csr-pain">痛点</a>全在这。</p><p><strong>SSR（服务端渲染）</strong> —— <strong>每次请求时，在服务器上</strong>渲染。每个请求都现算一份 HTML。→ 首屏快、内容实时，但每请求都要渲染，<a href="/Front2Full/manual/computer-programming/ssr/what-is-ssr">贵</a>。</p><p><strong>SSG（静态站点生成，Static Site Generation）</strong> —— <strong>构建时，一次性</strong>把所有页面渲染成静态 HTML 文件。之后所有用户拿到的是<strong>同一份</strong>预先生成好的 HTML，直接由 CDN 分发。→ 快到飞起、几乎零服务器成本，但内容<strong>冻结在构建那一刻</strong>，要更新就得重新构建。</p><p><strong>ISR（增量静态再生，Incremental Static Regeneration）</strong> —— <strong>SSG + 定期 / 按需再生</strong>。先像 SSG 一样发预生成的静态页（快），但会在后台<strong>按一定策略重新生成</strong>（比如「最多 60 秒旧」），让静态页也能「渐渐更新」。→ 兼得 SSG 的速度和「内容不至于太旧」。这是 SSG 和 SSR 之间的<strong>中间态</strong>，后面<a href="/Front2Full/manual/computer-programming/ssr/isr">专门一章</a>细讲。</p><h2 id="一张全景表" tabindex="-1">一张全景表 <a class="header-anchor" href="#一张全景表" aria-label="Permalink to &quot;一张全景表&quot;">​</a></h2><p>把它们并排比较，取舍就清楚了：</p><table tabindex="0"><thead><tr><th>策略</th><th>何时渲染</th><th>每个用户看到的</th><th>新鲜度</th><th>TTFB</th><th>扛并发</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>CSR</strong></td><td>客户端运行时</td><td>各自现画</td><td>实时</td><td>快（空壳）</td><td>好（服务器轻）</td><td>后台、仪表盘、内部工具</td></tr><tr><td><strong>SSR</strong></td><td>服务端每请求</td><td>服务器现画</td><td><strong>实时</strong></td><td><strong>慢</strong></td><td><strong>差（须靠缓存）</strong></td><td>个性化页、高频变动数据</td></tr><tr><td><strong>SSG</strong></td><td>构建时一次</td><td>同一份静态</td><td><strong>构建那刻（旧）</strong></td><td><strong>极快</strong></td><td><strong>极好</strong></td><td>博客、文档、营销页</td></tr><tr><td><strong>ISR</strong></td><td>构建 + 定期再生</td><td>同一份（定期换新）</td><td>近实时</td><td>极快</td><td>极好</td><td>电商列表、新闻、榜单</td></tr></tbody></table><p>盯着「新鲜度」和「扛并发」这两列看，你会发现一条<strong>核心矛盾</strong>：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>越新鲜，越难扛量；越好扛，越不新鲜。</strong></p><p>SSR 最新鲜（每请求现算），但正因为每请求现算，最难扛并发。SSG 最好扛（静态文件、CDN 分发），但内容最旧（冻在构建时）。这条矛盾，是整个渲染策略选择的主轴——而<strong>缓存，正是用来在这条轴上「作弊」的</strong>：它想让你既拿到接近 SSR 的新鲜度，又拿到接近 SSG 的扛量。这也是为什么本专栏把缓存当成重点。</p></div><h2 id="关键-它们不是「四选一」" tabindex="-1">关键：它们不是「四选一」 <a class="header-anchor" href="#关键-它们不是「四选一」" aria-label="Permalink to &quot;关键：它们不是「四选一」&quot;">​</a></h2><p>一个常见误解是「一个站点只能选一种」。其实现代框架里，<strong>渲染策略是「每个页面（甚至每个组件）分别选」的</strong>：</p><ul><li>博客文章页 → SSG（内容不常变，构建时生成）。</li><li>商品列表页 → ISR（内容会变但能容忍几十秒延迟）。</li><li>用户个人中心 → SSR（强个性化，必须实时）。</li><li>后台仪表盘 → CSR（SEO 无关，交互极频繁）。</li></ul><p><strong>同一个站点，不同页面用不同策略，是常态、也是最优解。</strong> 「精通 SSR」很大程度上就是「精通为每个页面挑对策略」。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>你可能还听过 <strong>SSG + 客户端补充</strong>（先发静态壳，再在客户端拉动态部分）、<strong>PPR（Partial Prerendering，部分预渲染）</strong> 等更细的组合。别被名词吓到——它们全都是在这张「构建时 / 请求时 / 运行时」的光谱上做<strong>混搭</strong>：哪部分能提前算就提前算（偏 SSG），哪部分必须实时就实时（偏 SSR）。抓住「何时渲染」这根轴，再花哨的组合都能看穿。</p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>CSR / SSR / SSG / ISR，本质是「何时、何地渲染」的不同答案，核心矛盾是<strong>新鲜度 vs 扛量</strong>，而缓存是用来突破这个矛盾的手段。它们不是四选一，而是<strong>按页面混搭</strong>。</p><p>渲染的地基打完了。第二站，我们看 SSR 这些年是怎么「变聪明」的——它没有停在「每请求傻傻地整页渲染」，而是学会了<strong>边算边发</strong>。下一章讲流式渲染：让浏览器不必等整页渲染完，而是<strong>一块一块</strong>地收到 HTML。👉 <a href="/Front2Full/manual/computer-programming/ssr/streaming">流式渲染：别等全部，边算边发</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] web.dev.「Rendering on the Web.」<a href="https://web.dev/articles/rendering-on-the-web" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-on-the-web</a> —— CSR/SSR/SSG 光谱与取舍。</li><li>[2] Next.js 文档.「Rendering: Static / Dynamic / ISR / PPR.」<a href="https://nextjs.org/docs/app/building-your-application/rendering" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/building-your-application/rendering</a> —— 各渲染策略与混搭。</li><li>[3] Vercel.「A Complete Guide to Incremental Static Regeneration.」<a href="https://vercel.com/blog/incremental-static-regeneration" target="_blank" rel="noreferrer">https://vercel.com/blog/incremental-static-regeneration</a> —— ISR 的定位。</li></ul>',25)])])}const h=r(s,[["render",a]]);export{c as __pageData,h as default};
